```typescript
import * as fs from 'fs';
import * as path from 'path';

// Read the reference format to understand structure
const expectedFormatPath = 'input/expected_format.json';
const csvPath = 'input/input.csv';

function main() {
    const content = fs.readFileSync(csvPath, 'utf-8');

    // Parse CSV - simple parsing without external library
    const lines = content.trim().split('\n');
    const headers = lines[0].split(',');

    // Find header indices
    const nameIdx = headers.indexOf('Name');
    const birthdayIdx = headers.indexOf('Birthday');
    const diedIdx = headers.indexOf('Died');
    const fatherIdx = headers.indexOf('Father');
    const motherIdx = headers.indexOf('Mother');
    const brotherIdx = headers.indexOf('Brother');
    const sisterIdx = headers.indexOf('Sister');

    const result: any[] = [];

    for (let i = 1; i < lines.length; i++) {
        // Split on comma but handle commas in names (unlikely)
        const values = lines[i].split(',');

        const firstName = values[nameIdx].trim().split(' ')[0];
        const lastName = values[nameIdx].trim().split(' ').pop();
        const birthdayStr = values[birthdayIdx]?.trim() || '';
        const age = calculateAgeAsOf(birthdayStr);

        const relatives: any[] = [];

        // Parse father
        if (values[fatherIdx] && values[fatherIdx].trim() !== 'null') {
            const fatherParts = values[fatherIdx].split(',');
            relatives.push({
                firstName: fatherParts[0],
                lastName: fatherParts[1],
                relationship: 'Father'
            });
        }

        // Parse mother
        if (values[motherIdx] && values[motherIdx].trim() !== 'null') {
            const motherParts = values[motherIdx].split(',');
            relatives.push({
                firstName: motherParts[0],
                lastName: motherParts[1],
                relationship: 'Mother'
            });
        }

        // Parse brother
        if (values[brotherIdx] && values[brotherIdx].trim() !== 'null') {
            const brotherParts = values[brotherIdx].split(',');
            relatives.push({
                firstName: brotherParts[0],
                lastName: brotherParts[1],
                relationship: 'Brother'
            });
        }

        // Parse sister
        if (values[sisterIdx] && values[sisterIdx].trim() !== 'null') {
            const sisterParts = values[sisterIdx].split(',');
            relatives.push({
                firstName: sisterParts[0],
                lastName: sisterParts[1],
                relationship: 'Sister'
            });
        }

        result.push({
            firstName,
            lastName,
            birthday: formatBirthday(birthdayStr),
            age,
            relatives
        });
    }

    // Output JSON to stdout
    console.log(JSON.stringify(result, null, 2));
}

function calculateAgeAsOf(birthdayStr: string): number {
    const [month, day, year] = birthdayStr.split('/').map(Number);
    const referenceDate = new Date('2025-07-01');
    const birthDate = new Date(year + '-' + String(month).padStart(2, '0') + '-' + String(day).padStart(2, '0'));

    let age = referenceDate.getFullYear() - birthDate.getFullYear();

    // Adjust if birthday hasn't passed yet in current year
    const refMonthDay = 7;
    if (refMonthDay < month || (refMonthDay === month && refDate.getDay() > day)) {
        age--;
    }

    return age;
}

function formatBirthday(birthdayStr: string): string {
    const [month, day, year] = birthdayStr.split('/').map(Number);
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

main();
